"""Pluggable embedding support for the metadata-aware RAG system.

The default is :class:`HashEmbeddings`, a deterministic, fully-offline
embedding based on hashed word/character n-grams. It requires no model
download and no network, which makes demos and tests reproducible.

In production you typically want a real model; :func:`build_embedding`
can return OpenAI or Ollama embeddings when configured and available,
falling back to the offline hash embeddings otherwise.
"""

from __future__ import annotations

import hashlib
import re
from typing import List, Optional

import numpy as np
from langchain_core.embeddings import Embeddings

_TOKEN_RE = re.compile(r"[a-z0-9]+", re.IGNORECASE)
_STOPWORDS = frozenset(
    """
    a an and are as at be but by for from if in into is it no not of on or
    such that the their then there these they this to was will with
    """.split()
)


def _tokens(text: str) -> List[str]:
    toks = _TOKEN_RE.findall(text.lower())
    return [t for t in toks if t not in _STOPWORDS]


def _char_ngrams(text: str, n: int) -> List[str]:
    text = re.sub(r"\s+", " ", text.lower()).strip()
    if len(text) < n:
        return [text] if text else []
    return [text[i : i + n] for i in range(len(text) - n + 1)]


def _hash_index(feature: str, buckets: int) -> int:
    return int(hashlib.md5(feature.encode("utf-8")).hexdigest(), 16) % buckets


def _hash_sign(feature: str) -> float:
    h = hashlib.sha256(feature.encode("utf-8")).hexdigest()
    return 1.0 if int(h[0], 16) % 2 == 0 else -1.0


class HashEmbeddings(Embeddings):
    """Deterministic offline embeddings via the hashing trick.

    Each text is mapped to a fixed-dimensional dense vector by hashing word
    unigrams/bigrams and character n-grams with random signs, then
    L2-normalizing. Cosine similarity between these vectors approximates
    lexical/semantic overlap well enough for offline demos and tests.
    """

    def __init__(self, dim: int = 512, word_ngram: int = 2, char_ngram: int = 3):
        self.dim = dim
        self.word_ngram = word_ngram
        self.char_ngram = char_ngram

    def _embed_one(self, text: str) -> np.ndarray:
        vec = np.zeros(self.dim, dtype=np.float64)
        features = set()

        toks = _tokens(text)
        for t in toks:
            features.add("w:" + t)
        for n in range(2, self.word_ngram + 1):
            for i in range(len(toks) - n + 1):
                features.add("w:" + " ".join(toks[i : i + n]))
        for n in range(2, self.char_ngram + 1):
            for cg in _char_ngrams(text, n):
                features.add(f"c{n}:{cg}")

        for f in features:
            idx = _hash_index(f, self.dim)
            vec[idx] += _hash_sign(f)

        norm = np.linalg.norm(vec)
        if norm > 0:
            vec /= norm
        return vec

    def embed_documents(self, texts: List[str]) -> List[List[float]]:
        return [self._embed_one(t).tolist() for t in texts]

    def embed_query(self, text: str) -> List[float]:
        return self._embed_one(text).tolist()


def build_embedding(prefer: str = "local", **kwargs) -> Embeddings:
    """Return an :class:`Embeddings` instance.

    ``prefer`` selects the preferred backend:

    * ``"local"``   -> :class:`HashEmbeddings` (offline, always works)
    * ``"openai"``  -> ``langchain_openai.OpenAIEmbeddings`` if an
      ``OPENAI_API_KEY`` environment variable is present
    * ``"ollama"``  -> ``langchain_ollama.OllamaEmbeddings``

    If the preferred backend cannot be constructed, the offline hash
    embeddings are returned as a fallback.
    """
    if prefer == "openai":
        try:
            import os

            from langchain_openai import OpenAIEmbeddings

            if os.environ.get("OPENAI_API_KEY"):
                return OpenAIEmbeddings(
                    model=kwargs.get("openai_model", "text-embedding-3-small")
                )
        except Exception:
            pass

    if prefer == "ollama":
        try:
            from langchain_ollama import OllamaEmbeddings

            return OllamaEmbeddings(model=kwargs.get("ollama_model", "nomic-embed-text"))
        except Exception:
            pass

    return HashEmbeddings(
        dim=kwargs.get("dim", 512),
        word_ngram=kwargs.get("word_ngram", 2),
        char_ngram=kwargs.get("char_ngram", 3),
    )

