"""Metadata-aware document ranking.

Given a user query, an optional set of parsed metadata filters, and the
candidate documents returned by the vector store, :class:`MetadataRanker`
computes a final relevance score for every candidate:

    final = semantic_weight * semantic_score
          + metadata_weight * metadata_score

where ``metadata_score`` is a weighted blend of:

* explicit filter-field matches (category, source, author, doc_type, region)
* tag overlap with the query
* keyword overlap between the query and the document's metadata text
* a priority boost (higher ``priority`` metadata -> higher score)
* a recency boost (newer ``date`` metadata -> higher score)

Every document receives a ``retrieval`` dict in its metadata with the score
breakdown, so ranking is transparent and debuggable.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import date as _date
from typing import Any, Dict, List, Optional

from langchain_core.documents import Document

_STOPWORDS = frozenset(
    """
    a an and are as at be but by for from if in into is it no not of on or
    such that the their then there these they this to was will with
    """.split()
)

_TOKEN_RE = re.compile(r"[a-z0-9]+")


@dataclass
class RankWeights:
    """Weights for the final relevance score and its components."""

    semantic: float = 0.55
    metadata: float = 0.45
    field_match: Dict[str, float] = field(
        default_factory=lambda: {
            "category": 0.30,
            "source": 0.25,
            "author": 0.15,
            "doc_type": 0.15,
            "region": 0.15,
        }
    )
    tags: float = 0.25
    keywords: float = 0.20
    priority: float = 0.15
    recency: float = 0.10


def _as_list(value: Any) -> List[str]:
    if value is None:
        return []
    if isinstance(value, (list, tuple, set)):
        return [str(v).lower() for v in value]
    return [str(value).lower()]


def _field_match(want: Any, have: Any) -> float:
    """Binary match between a filter value and a document metadata value."""
    # range operator dict, e.g. {'$gte': 4} (priority) or {'$gte': '2025-01-01'} (date)
    if isinstance(want, dict) and any(k.startswith("$") for k in want):
        try:
            h = have
            for op, val in want.items():
                if isinstance(h, str) and str(val).replace("-", "", 1).isdigit():
                    h = float(h)  # numeric string comparison
                v = float(val) if isinstance(val, (int, float)) else val
                if op == "$eq" and not (h == v):
                    return 0.0
                if op == "$ne" and not (h != v):
                    return 0.0
                if op == "$gt" and not (h > v):
                    return 0.0
                if op == "$gte" and not (h >= v):
                    return 0.0
                if op == "$lt" and not (h < v):
                    return 0.0
                if op == "$lte" and not (h <= v):
                    return 0.0
            return 1.0
        except (TypeError, ValueError):
            return 0.0

    want_values = _as_list(want)
    have_values = _as_list(have)
    for w in want_values:
        for h in have_values:
            if w == h or w in h or h in w:
                return 1.0
    return 0.0


class MetadataRanker:
    """Re-scores retrieved documents with metadata-aware relevance."""

    def __init__(self, weights: Optional[RankWeights] = None):
        self.w = weights or RankWeights()

    # ------------------------------------------------------------------ #
    def score(
        self,
        query: str,
        filters: Dict[str, Any],
        documents: List[Document],
        semantic_scores: Optional[List[float]] = None,
    ) -> List[Document]:
        """Rank ``documents`` in place of metadata, returning them sorted.

        ``semantic_scores`` are cosine similarities from the vector store
        (higher = more similar). When ``None`` (e.g. metadata-only search),
        the final score equals the metadata score alone.
        """
        if semantic_scores is not None and len(semantic_scores) == len(documents):
            lo, hi = min(semantic_scores), max(semantic_scores)
            span = hi - lo
            norm = [(s - lo) / span if span > 1e-9 else 0.5 for s in semantic_scores]
        else:
            norm = [0.5] * len(documents)

        dates = [d.metadata.get("date", "") for d in documents]
        max_date = max((d for d in dates if d), default="")

        scored: List[tuple] = []
        for doc, sem in zip(documents, norm):
            meta_score = self._metadata_score(query, filters, doc, max_date)
            if semantic_scores is not None:
                final = self.w.semantic * sem + self.w.metadata * meta_score
            else:
                final = meta_score
            doc.metadata["retrieval"] = {
                "semantic": round(float(sem), 4),
                "metadata": round(float(meta_score), 4),
                "final": round(float(final), 4),
            }
            scored.append((float(final), doc))

        scored.sort(key=lambda x: -x[0])
        for rank, (_, doc) in enumerate(scored, 1):
            doc.metadata["retrieval"]["rank"] = rank
        return [doc for _, doc in scored]

    # ------------------------------------------------------------------ #
    def _metadata_score(
        self,
        query: str,
        filters: Dict[str, Any],
        doc: Document,
        max_date: str,
    ) -> float:
        meta = doc.metadata
        components: List[tuple] = []

        def add(weight: float, value: float) -> None:
            if weight > 0 and value is not None:
                components.append((weight, max(0.0, min(1.0, float(value)))))

        # 1) explicit filter-field matches
        for fld, weight in self.w.field_match.items():
            if fld in filters:
                add(weight, _field_match(filters[fld], meta.get(fld)))

        # 2) tag overlap between query and document tags
        qtags = self._query_tags(query, filters)
        if qtags:
            dtags = set(_as_list(meta.get("tags")))
            if dtags:
                overlap = len(qtags & dtags) / max(1, len(qtags))
                add(self.w.tags, overlap)

        # 3) keyword overlap between query and metadata text
        meta_text = " ".join(
            str(meta.get(k, ""))
            for k in ("title", "category", "source", "author", "doc_type", "region", "tags")
        )
        qtoks = {t for t in _TOKEN_RE.findall(query.lower()) if t not in _STOPWORDS}
        if qtoks and meta_text:
            hit = sum(1 for t in qtoks if t in meta_text.lower())
            add(self.w.keywords, hit / len(qtoks))

        # 4) priority boost (metadata priority in [1..5])
        prio = meta.get("priority")
        if isinstance(prio, (int, float)):
            add(self.w.priority, (float(prio) - 1.0) / 4.0)

        # 5) recency boost relative to the newest candidate
        date_str = str(meta.get("date", ""))
        if max_date and date_str:
            try:
                cur = _date.fromisoformat(date_str)
                mx = _date.fromisoformat(max_date)
                days = (mx - cur).days
                add(self.w.recency, max(0.0, 1.0 - days / 730.0))
            except ValueError:
                pass

        total_weight = sum(w for w, _ in components)
        if total_weight == 0:
            return 0.0
        return sum(w * v for w, v in components) / total_weight

    # ------------------------------------------------------------------ #
    @staticmethod
    def _query_tags(query: str, filters: Dict[str, Any]) -> set:
        tags = set(_as_list(filters.get("tags")))
        # also pick up tag-like words mentioned in the query text
        for t in _TOKEN_RE.findall(query.lower()):
            if t not in _STOPWORDS and len(t) > 2:
                tags.add(t)
        return tags
